#!/usr/bin/env bash
# The coverage axis (A1 of the evaluation plan). Removes every image this experiment uses, so that the first prepare
# pulls the newest :dev generator and engine images and rebuilds the client images on them; generates the
# combinations; then runs every fraction of vary-endpoint-fraction.json (scripts/vary-endpoint-fraction.js: per
# fraction it regenerates, checks the data are those of the other fractions, and runs the fraction's combinations).
# The images are removed only here, never between fractions: every fraction must be generated by the same generator,
# or the fingerprint check stops the run.
# Start detached: setsid nohup ./run-vary.sh > output/run-vary.log 2>&1 < /dev/null &
# Progress: output/STATUS. Logs: output/generate-combinations.log, output/vary.log.
# Extra arguments go to the script, e.g. ./run-vary.sh --force.
set -uo pipefail
cd "$(dirname "$0")"
source ~/.nvm/nvm.sh >/dev/null
mkdir -p output
status() { echo "$(date '+%F %T') $*" | tee -a output/STATUS; }

status "start (vary endpoint fraction)"
images=(
  rubeneschauzier/fedshop-discovery-generator:dev
  rubeneschauzier/comunica-query-sparql-link-traversal-solid-derived-resources:dev
  "$(sed -n 's/.*"virtuosoImage": "\([^"]*\)".*/\1/p' jbr-experiment.json.template)"
  $(docker images --format '{{.Repository}}:{{.Tag}}' | grep '^jbr-experiment-fedshop-discovery-full-experiment-combination_')
)
for image in "${images[@]}"; do
  docker image inspect "$image" > /dev/null 2>&1 && docker rmi -f "$image" >> output/STATUS 2>&1
done
status "removed images: ${images[*]}"

npx jbr generate-combinations > output/generate-combinations.log 2>&1 || { status "FAILED: generate-combinations"; exit 1; }
status "running the fractions (log: output/vary.log)"
npm run vary -- run "$@" > output/vary.log 2>&1 || { status "FAILED: vary (see the end of output/vary.log)"; exit 1; }
status "DONE: results in output-<fraction>/combination_<i>/ (1 = pattern-only, 2 = derived full + extended blocks + bound composites, 3 = traversal only; see each output-<fraction>/endpoint-fraction.json)"
